        const MAX_POINTS = 32;
        const sliders = {
            charm: document.getElementById('charm'),
            intelligence: document.getElementById('intelligence'),
            health: document.getElementById('health'),
            wealth: document.getElementById('wealth'),
            happiness: document.getElementById('happiness')
        };

        const values = {
            charm: document.getElementById('charm-value'),
            intelligence: document.getElementById('intelligence-value'),
            health: document.getElementById('health-value'),
            wealth: document.getElementById('wealth-value'),
            happiness: document.getElementById('happiness-value')
        };

