                const val = sliders[key].value;
                values[key].textContent = val;
                results[key].textContent = val;
            });
        }

        Object.values(sliders).forEach(slider => {
            slider.addEventListener('input', function() {
                const total = getTotal();
                if (total > MAX_POINTS) {
                    const excess = total - MAX_POINTS;
                    this.value = parseInt(this.value) - excess;
                }
                updateDisplay();
            });
        });

        function randomize() {
            let remaining = MAX_POINTS;
            const keys = Object.keys(sliders);
            const randomValues = {};

            keys.forEach((key, index) => {
                if (index === keys.length - 1) {
                    randomValues[key] = remaining;
                } else {
                    const max = remaining - (keys.length - index - 1);
                    const val = Math.floor(Math.random() * (max + 1));
                    randomValues[key] = val;
                    remaining -= val;
                }
            });

            Object.keys(randomValues).forEach(key => {
                sliders[key].value = randomValues[key];
            });

            updateDisplay();
        }

        updateDisplay();
    </script>
