                    const max = Math.min(10, remaining - (keys.length - index - 1));
                    const val = Math.floor(Math.random() * (max + 1));
                    randomValues[key] = val;
                    remaining -= val;
                } else {
                    // 最后一个属性获得剩余所有点数
                    randomValues[key] = remaining;
                }
            });

            // 如果最后一个属性超过10，需要重新分配
            if (randomValues[keys[keys.length - 1]] > 10) {
                // 重新随机，确保每项都在0-10之间且总和为32
                let attempts = 0;
                while (attempts < 100) {
                    remaining = MAX_POINTS;
                    let valid = true;

                    keys.forEach((key, index) => {
                        if (index < keys.length - 1) {
                            const val = Math.floor(Math.random() * 11); // 0-10
                            randomValues[key] = val;
                            remaining -= val;
                        } else {
                            randomValues[key] = remaining;
                            if (remaining < 0 || remaining > 10) {
                                valid = false;
                            }
                        }
                    });

                    if (valid) break;
                    attempts++;
                }

                // 如果100次都没成功，使用平均分配
                if (attempts >= 100) {
                    const avg = Math.floor(MAX_POINTS / keys.length);
                    let leftover = MAX_POINTS - (avg * keys.length);
                    keys.forEach(key => {
                        randomValues[key] = avg;
                        if (leftover > 0) {
                            randomValues[key]++;
                            leftover--;
                        }
                    });
                }
            }

            Object.keys(randomValues).forEach(key => {
                sliders[key].value = randomValues[key];
            });

            updateDisplay();
        }

        function generateResultText() {
            const randomAge = Math.floor(Math.random() * 10) + 1;
            const attributes = {
                charm: sliders.charm.value,
                intelligence: sliders.intelligence.value,
                health: sliders.health.value,
                wealth: sliders.wealth.value,
                happiness: sliders.happiness.value
            };

            return `性别：随机；年龄：${randomAge}；城市：随机；{魅力: ${attributes.charm}, 智力: ${attributes.intelligence}, 健康: ${attributes.health}, 富裕: ${attributes.wealth}, 幸福度: ${attributes.happiness}}`;
        }

        function copyResult() {
            const text = generateResultText();

            // 方案1: 使用 execCommand
            const input = document.createElement('input');
            input.value = text;
            input.style.position = 'fixed';
            input.style.opacity = '0';
            document.body.appendChild(input);
            input.select();
            input.setSelectionRange(0, 99999);

            try {
                const successful = document.execCommand('copy');
                if (successful) {
                    showCopyStatus('✅ 复制成功！', 'success');
                } else {
                    // 方案1失败，尝试方案2
                    copyWithClipboardJS(text);
                }
            } catch (err) {
                // 方案1出错，尝试方案2
                copyWithClipboardJS(text);
            }

            document.body.removeChild(input);
        }

        function copyWithClipboardJS(text) {
            // 使用 Clipboard.js 作为备用方案
            const tempBtn = document.createElement('button');
            tempBtn.setAttribute('data-clipboard-text', text);
            document.body.appendChild(tempBtn);

            const clipboard = new ClipboardJS(tempBtn);

            clipboard.on('success', function(e) {
                showCopyStatus('✅ 复制成功！', 'success');
                e.clearSelection();
                clipboard.destroy();
                document.body.removeChild(tempBtn);
            });

            clipboard.on('error', function(e) {
                showCopyStatus('❌ 复制失败', 'error');
                clipboard.destroy();
                document.body.removeChild(tempBtn);
            });

            tempBtn.click();
        }

        function showCopyStatus(message, type) {
            const originalText = copyBtn.textContent;
            copyBtn.textContent = message;
            copyBtn.classList.add(type);

            setTimeout(() => {
                copyBtn.textContent = originalText;
                copyBtn.classList.remove(type);
            }, 2000);
        }

        updateDisplay();
    </script>
